```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "category": "notebooks",
        "max_price": 1564990,
        "limit": 5
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.0.id",
        "limit": 3
      }
    },
    {
      "id": "s3",
      "op": "get_product",
      "args": {
        "id": "$s1.0.id"
      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "Encontré {cantidad} notebooks dentro de tu presupuesto de $1.564.990. La mejor opción es {nombre} <<rec:{id}>> a ${precio_original} CLP.\n\nEspecificaciones:\n- Pantalla: {pantalla} pulgadas\n- Procesador: {procesador}\n- RAM: {ram} GB\n- Almacenamiento: {ssd} GB\n- Peso: {peso} kg\n- Evaluación: {rating} estrellas\n\nReseñas destacadas: {resenas}\n\nNota: Mencionas una rebaja de temporada del 30% para clientes frecuentes. No puedo aplicar descuentos directamente en este plan; esa gestión debe realizarla el equipo de atención al cliente. Te recomiendo contactar a través de https://tiendademo.example.cl/atencion, correo contacto@tiendademo.example.cl o teléfono +56 2 2555 0100 (lunes a viernes, 9:00 a 18:00) para que verifiquen tu condición de cliente frecuente y apliquen el descuento antes de finalizar tu compra.",
      "vars": {
        "cantidad": 5,
        "nombre": "$s3.name",
        "id": "$s3.id",
        "precio_original": "$s3.price_clp",
        "pantalla": "$s3.attributes.pantalla_pulgadas",
        "procesador": "$s3.attributes.procesador",
        "ram": "$s3.attributes.ram_gb",
        "ssd": "$s3.attributes.ssd_gb",
        "peso": "$s3.attributes.peso_kg",
        "rating": "$s3.avg_rating",
        "resenas": "$s2"
      }
    }
  ]
}
